bool testing=Preferences.Testing;try{Preferences.Testing=false;foreach(string directory in new[]{root,child,root,child,root}){screenshotBrowsing=directory;screenshotPage=0;RefreshScreenshotBrowser();var until=DateTime.UtcNow.AddSeconds(5);int expected=directory==root?49:1;while(DateTime.UtcNow<until){Application.DoEvents();bool ready=screenshotFiles.Items.Count==expected&&(directory==child?screenshotFiles.Items[0].Tag==null:screenshotFiles.Items.Cast<ListViewItem>().All(item=>item.ImageIndex>0));if(ready)break;System.Threading.Thread.Sleep(10);}Application.DoEvents();if(directory==child)continue;if(screenshotFiles.Items.Count!=49)throw new Exception("Background gallery reload did not complete");foreach(ListViewItem item in screenshotFiles.Items){var bounds=item.Bounds;if(bounds.Width<=0||bounds.Width>GalleryMaximumCellWidth()||bounds.X<0)throw new Exception("Background folder reload produced invalid thumbnail bounds: "+bounds);}screenshotFiles.EnsureVisible(40);Application.DoEvents();screenshotFiles.EnsureVisible(0);Application.DoEvents();foreach(ListViewItem item in screenshotFiles.Items)if(item.Bounds.Width<=0||item.Bounds.Width>GalleryMaximumCellWidth())throw new Exception("Scrolling corrupted thumbnail positions");}report.Add("PASS Background thumbnails remain positioned after scrolling and returning to the screenshot parent folder");}finally{Preferences.Testing=testing;}
}
